/// Implements the default behaviour which is to synchronously remove the handler from the pipeline. Thanks to this, stateless `ChannelHandler`s can just use `RemovableChannelHandler` as a marker-protocol and declare themselves as removable without writing any extra code.
public func removeHandler(context: ChannelHandlerContext, removalToken: ChannelHandlerContext.RemovalToken) {
    precondition(context.handler === self)
    context.leavePipeline(removalToken: removalToken)
}
