public func `open`(
    atPath path: FilePath,
    mode: FileDescriptor.AccessMode,
    options: FileDescriptor.OpenOptions,
    permissions: FilePermissions?,
    retryOnInterrupt: Bool = true
) -> Result<FileDescriptor, Errno> {
