/// Runs the submitted closure if the thread pool is still active, otherwise throw an error. The closure will be run on the thread pool, such that we can do blocking work.
public func runIfActive<T: Sendable>(_ body: @escaping @Sendable () throws -> T) async throws -> T {
    let workID = self.nextWorkID.loadThenWrappingIncrement(ordering: .relaxed)

    return try await withTaskCancellationHandler {
        try await withCheckedThrowingContinuation { (cont: CheckedContinuation<T, Error>) in
            self._submit(id: workID) { shouldRun in
                switch shouldRun {
                case .active:
                    let result = Result(catching: body)
                    cont.resume(with: result)
                case .cancelled:
                    cont.resume(throwing: CancellationError())
                }
            }
        }
    } onCancel: {
        self._workAvailable.withLock {
            self._cancelledWorkIDs.insert(workID)
            return (workDelta: 0, signal: .none, result: ())
        }
    }
}
