                msgs[c] = MMsgHdr(msg_hdr: msg, msg_len: 0)
            }
            c += 1
        }
        defer {
            for i in 0..<c {
                storageRefs[i].release()
            }
        }
        return try body(UnsafeMutableBufferPointer(start: msgs.baseAddress!, count: c))
    }
}
