            returns: [
                .processed(Socket.writevLimitBytes),
                // Xcode
                .processed(23),
                // needs
                .processed(Socket.writevLimitBytes),
                // help
                .processed(23 + 100),
            ],
            promiseStates: [
                [false, false, false],
                // Xcode
                [true, false, false],
                // needs
                [true, false, false],
                // help
                [true, true, true],
