/// This function will wait for an event loop wakeup until it unblocks. If the event loop is currently executing then it will not be woken: as a result, consider using `assertParkedRightNow` before the event that you want to trigger the wakeup, and before calling this code.
func assertWakeup(file: StaticString = #filePath, line: UInt = #line) throws {
    SAL.printIfDebug("\(#function)")
    try self.wakeups.takeValue()
    try self.assertSyscallAndReturn(.returnSelectorEvent(nil), file: (file), line: line) { syscall in
        if case .whenReady(.block) = syscall {
            return true
        } else {
            return false
        }
    }
}
